public class CompassTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("NORTH.right()", Compass.Direction.EAST, Compass.Direction.NORTH.right());
        check("WEST.right()", Compass.Direction.NORTH, Compass.Direction.WEST.right());
        check("NORTH.left()", Compass.Direction.WEST, Compass.Direction.NORTH.left());
        check("EAST.left()", Compass.Direction.NORTH, Compass.Direction.EAST.left());
        check("WEST.left()", Compass.Direction.SOUTH, Compass.Direction.WEST.left());
        check("SOUTH.opposite()", Compass.Direction.NORTH, Compass.Direction.SOUTH.opposite());
        check("EAST.opposite()", Compass.Direction.WEST, Compass.Direction.EAST.opposite());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
